/** Everything the scorecard shows for one period (plain data, so a saved record can be shown exactly as it was). */
export function scorecard(P) {
  const cfg = config();
  // Volume (billing drops): month aggregates, summed across files.
  const vol = Object.fromEntries(P.months.map(ym => [ym, null]));
  const expedited = [];
  for (const b of store.rows('elxBilling')) {
    for (const [ym, M] of Object.entries(b.months || {})) if (ym in vol) { vol[ym] ||= emptyVol(); for (const k of VOL_KEYS) vol[ym][k] += num(M[k]); }
    for (const e of b.expeditedList || []) if (inP(P, e.date)) expedited.push(e);
  }
  const volTotal = emptyVol(); for (const M of Object.values(vol)) if (M) for (const k of VOL_KEYS) volTotal[k] += M[k];
  const files = store.rows('elxBilling').filter(b => b.to >= P.from && b.from <= P.to).sort((a, b) => a.from.localeCompare(b.from)).map(b => ({ from: b.from, to: b.to, file: b.file }));

  // Cycle counts.
  const cyc = P.months.map(ym => ({ ym, ...(store.rows('elxCycle').find(c => c.month === ym) || {}) }));
  const cycHave = cyc.filter(c => c.binAcc !== undefined);
  const cycAvg = k => avg(cycHave.map(c => c[k]).filter(x => typeof x === 'number'));

  // OTIF-driven accuracy.
  const otif = store.rows('otif').filter(r => isElx(r.customer) && inP(P, r.date));
  const isK = (r, ks) => ks.includes(key(r.type)) || ks.includes(key(r.category));
  const otifRow = r => ({ id: r.id, date: r.date, type: r.type || '', category: r.category || '', responsible: r.responsible || '', description: r.description || '' });
  const outErr = otif.filter(r => isK(r, ['MISPICK', 'MISSHIP'])).sort((a, b) => a.date.localeCompare(b.date));
  const inErr = otif.filter(r => isK(r, ['INBOUNDDISCREPANCY'])).sort((a, b) => a.date.localeCompare(b.date));
  const byMonth = (list, denomKey) => P.months.map(ym => {
    const n = list.filter(r => r.date.startsWith(ym)).length, d = vol[ym]?.[denomKey] ?? '';
    return { ym, n, d, pct: d === '' ? '' : d > 0 ? 1 - n / d : '' };
  });
  const fulfill = { months: byMonth(outErr, 'ordersOut'), n: outErr.length, d: volTotal.ordersOut, pct: volTotal.ordersOut > 0 ? 1 - outErr.length / volTotal.ordersOut : '', list: outErr.map(otifRow) };
  const invAcc = { months: byMonth(inErr, 'ordersIn'), n: inErr.length, d: volTotal.ordersIn, pct: volTotal.ordersIn > 0 ? 1 - inErr.length / volTotal.ordersIn : '', list: inErr.map(otifRow) };

  // Damage: qty ÷ cases received (skids in × cases per skid).
  const dmg = store.rows('damage').filter(r => isElx(r.customer) && inP(P, r.date)).sort((a, b) => a.date.localeCompare(b.date));
  const dmgMonths = P.months.map(ym => {
    const q = dmg.filter(r => r.date.startsWith(ym)).reduce((a, r) => a + num(r.qty), 0), cases = vol[ym] ? vol[ym].skidsIn * cfg.casesPerSkid : '';
    return { ym, qty: q, cases, pct: cases === '' ? '' : safeDiv(q, cases) };
  });
  const dmgQty = dmg.reduce((a, r) => a + num(r.qty), 0), dmgCases = volTotal.skidsIn * cfg.casesPerSkid;
  const damage = { months: dmgMonths, qty: dmgQty, cases: dmgCases, value: dmg.reduce((a, r) => a + num(r.value), 0), pct: safeDiv(dmgQty, dmgCases),
    list: dmg.map(r => ({ id: r.id, date: r.date, damageType: r.damageType || '', cause: r.cause || '', responsible: r.responsible || '', qty: num(r.qty), unit: r.unit || '', value: num(r.value), stage: r.stage || '' })) };

  const trucks = truckStats(P, r => isElx(r.customer || CUSTOMER), cfg);
  const rail = railStats(P, isElx);

  // NCRs (Electrolit USA Audit OS&D reports) dated in the period.
  const ncr = ncrStats(P, volTotal, cfg);

  const osha = oshaIndex(P, BUILDING);

  const ins = config().insurance || {};
  return {
    period: P, cfg: { casesPerSkid: cfg.casesPerSkid, onTimeMin: cfg.onTimeMin, holdMin: cfg.holdMin }, builtAt: new Date().toISOString(),
    volume: { months: P.months.map(ym => ({ ym, ...(vol[ym] || {}), has: !!vol[ym] })), total: volTotal, files, expedited },
    cycle: { months: cyc.map(c => ({ ym: c.ym, has: c.binAcc !== undefined, totalLocations: c.totalLocations ?? '', counted: c.counted ?? '', pctComplete: c.pctComplete ?? '', countAcc: c.countAcc ?? '', binAcc: c.binAcc ?? '', invAcc: c.invAcc ?? '', netVar: c.netVar ?? '', file: c.file || '' })),
      binAcc: cycAvg('binAcc'), countAcc: cycAvg('countAcc'), invAcc: cycAvg('invAcc'), pctComplete: cycAvg('pctComplete') },
    fulfill, invAcc, damage, trucks, rail, osha, ncr, insurance: ins,
  };
}

