ATL_SRC.push(['@atl/views/logs.js', 0, `// Generic searchable / filterable log table with add / edit / delete, driven by schema.js.
import { store } from '@atl/store.js';
import { LOGS } from '@atl/schema.js';
import { derive } from '@atl/calc.js';
import { esc, yearOf, downloadXLSX, toast, $, $$, isISO, fmtNum, fmtPct, norm } from '@atl/util.js';
import { page, table, openForm, kpi, chart, chartBox } from '@atl/ui.js';
import { openWriteUp } from '@atl/views/writeup.js';
import { importEmployeeIds } from '@atl/views/empids.js';
import { promptSafetyReport, isRecordableType, linkedReport } from '@atl/forms/incident.js';
import { promptOtifEmail } from '@atl/forms/otifemail.js';

const state = {}; // per-log UI state: {q, year, facility, employee, sort, dir, limit, ids}

export function logState(key) {
  return (state[key] ||= { q: '', year: 'all', facility: '', employee: '', sort: null, dir: -1, limit: 200, ids: null });
}

/** Columns visible in the table for a log definition. */
export function visibleFields(def) {
  return def.fields.filter(f => !f.hideInTable && (!f.confidential || store.can('confidential')));
}

/** Filter + sort rows for a log according to UI state. extraFilter(row) optional. */
export function filteredRows(coll, def, st, extraFilter) {
  let rows = derive(coll);
  if (extraFilter) rows = rows.filter(extraFilter);
  if (st.ids) { const set = new Set(st.ids); rows = rows.filter(r => set.has(r.id)); }
  if (st.year !== 'all' && def.dateKey) rows = rows.filter(r => String(yearOf(r[def.dateKey])) === String(st.year));
  if (st.facility && def.facilityKey) rows = rows.filter(r => String(r[def.facilityKey] ?? '') === st.facility);
  // Exact employee match (from a scorecard link) — unlike search, "JOHN" won't also match "JOHNSON".
  if (st.employee) rows = rows.filter(r => norm(r.employee) === norm(st.employee));
  if (st.q) {
    const q = st.q.toLowerCase();
    rows = rows.filter(r => [r.id, ...def.fields.map(f => r[f.key])].some(v => String(v ?? '').toLowerCase().includes(q)));
  }
  const key = st.sort || def.dateKey || def.sortKey || 'id';
  const dir = st.sort ? st.dir : def.dateKey ? -1 : 1;
  return [...rows].sort((a, b) => {
    const x = a[key] ?? '', y = b[key] ?? '';
    const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y), undefined, { numeric: true });
    return c * dir || String(a.id).localeCompare(String(b.id), undefined, { numeric: true }) * dir;
  });
}

/** Renders toolbar + table. Used by the log route and the rail customer tab. */
export function logBlock(coll, opts = {}) {
  const def = LOGS[coll], st = logState(opts.stateKey || coll);
  const rows = filteredRows(coll, def, st, opts.filter);
  const fields = visibleFields(def);
  const years = def.dateKey ? [...new Set(derive(coll).map(r => yearOf(r[def.dateKey])).filter(Boolean))].sort().reverse() : [];
  // The sorted column shows ▴/▾ (default: newest first on the date column).
  const sortKey = st.sort || def.dateKey || def.sortKey || 'id', sortDir = st.sort ? st.dir : def.dateKey ? -1 : 1;
  const arrow = k => (k === sortKey ? (sortDir > 0 ? ' ▴' : ' ▾') : '');
  const cols = [
    ...(def.idLabel ? [{ label: def.idLabel + arrow('id'), key: 'id', sort: 'id', cls: 'mono' }] : []),
    // t-<type> lets the stylesheet keep short values (dates, badges, numbers) on one line.
    ...fields.map(f => ({ label: f.label + arrow(f.key), key: f.key, type: f.type || (f.calc ? 'badge' : 'text'), sort: f.key, cls: [\`t-\${f.type || (f.calc ? 'badge' : 'text')}\`, f.type === 'textarea' ? 'clip' : '', f.cls || '', f.key === sortKey ? 'sorted' : ''].join(' ').trim() })),
  ];
  const canAdd = opts.canAdd ?? (def.adminOnly ? store.can('admin') : store.can('edit'));
  const filtered = st.q || st.year !== 'all' || st.facility;
  const toolbar = \`
    <div class="toolbar">
      <input type="search" class="search" placeholder="Search \${esc(def.short)}…" value="\${esc(st.q)}" data-q aria-label="Search \${esc(def.short)}">
      \${years.length ? \`<select data-year aria-label="Year"><option value="all">All years</option>\${years.map(y => \`<option \${String(y) === String(st.year) ? 'selected' : ''}>\${y}</option>\`).join('')}</select>\` : ''}
      \${def.facilityKey ? \`<select data-fac aria-label="Facility"><option value="">All facilities</option>\${store.settings.lists.facilities.map(f => \`<option \${f === st.facility ? 'selected' : ''}>\${esc(f)}</option>\`).join('')}</select>\` : ''}
      \${st.employee ? \`<button type="button" class="btn ghost small emp-chip" data-clear-employee title="Show everyone">Employee: \${esc(String(st.employee).toUpperCase())} ✕</button>\` : ''}
      \${filtered ? '<button type="button" class="btn ghost small" data-clear-filters>Clear filters ✕</button>' : ''}
      \${st.ids ? \`<button class="btn ghost small" data-clear-ids>Showing \${st.ids.length} flagged rows ✕</button>\` : ''}
      <span class="count" aria-live="polite">\${rows.length.toLocaleString()} row\${rows.length === 1 ? '' : 's'}</span>
      <span class="grow"></span>
      <button class="btn ghost" data-xlsx title="Download the rows shown (current filters) as an Excel workbook">⬇ Export to Excel</button>
      \${canAdd ? \`<button class="btn primary" data-add>+ Add</button>\` : ''}
    </div>\`;
  const more = rows.length > st.limit ? \`<div class="more"><button class="btn ghost" data-more>Show \${Math.min(st.limit, rows.length - st.limit)} more</button></div>\` : '';
  const empty = st.q || st.year !== 'all' || st.facility || st.employee || st.ids ? 'No entries match these filters — try clearing the search or choosing All years.' : 'No entries yet.';
  return \`<div data-log="\${coll}" data-state="\${opts.stateKey || coll}" class="log-block">\${toolbar}<div class="log-scroll">\${table(cols, rows, { max: st.limit, rowAttr: r => \`data-id="\${esc(r.id)}" class="clickable" tabindex="0"\`, empty })}</div>\${more}</div>\`;
}

/** Wire events for every [data-log] block inside root. rerender() redraws the view. */
export function bindLogs(root, rerender, opts = {}) {
  for (const block of $$('[data-log]', root)) {
    const coll = block.dataset.log, def = LOGS[coll], st = logState(block.dataset.state);
    const q = $('[data-q]', block);
    let t;
    q?.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => { st.q = q.value; st.limit = 200; rerender(); setTimeout(() => { const n = $(\`[data-state="\${block.dataset.state}"] [data-q]\`); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $('[data-year]', block)?.addEventListener('change', e => { st.year = e.target.value; rerender(); });
    $('[data-fac]', block)?.addEventListener('change', e => { st.facility = e.target.value; rerender(); });
    $('[data-clear-filters]', block)?.addEventListener('click', () => { Object.assign(st, { q: '', year: 'all', facility: '', employee: '', limit: 200 }); rerender(); });
    $('[data-clear-employee]', block)?.addEventListener('click', () => {
      st.employee = '';
      if (location.hash.includes('employee=')) location.hash = location.hash.split('?')[0]; else rerender();
    });
    $('[data-clear-ids]', block)?.addEventListener('click', () => {
      st.ids = null;
      if (location.hash.includes('ids=')) location.hash = location.hash.split('?')[0]; else rerender();
    });
    $('[data-more]', block)?.addEventListener('click', () => { st.limit += 200; rerender(); });
    $$('th[data-sort]', block).forEach(th => {
      // Sortable headings work from the keyboard too (Tab to a heading, Enter or Space to sort).
      th.tabIndex = 0; th.setAttribute('role', 'button'); th.setAttribute('aria-label', \`Sort by \${th.textContent.replace(/[▴▾]/g, '').trim()}\`);
      const go = () => { st.dir = st.sort === th.dataset.sort ? -st.dir : 1; st.sort = th.dataset.sort; rerender(); document.querySelector(\`[data-state="\${block.dataset.state}"] th[data-sort="\${th.dataset.sort}"]\`)?.focus(); };
      th.addEventListener('click', go);
      th.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); } });
    });
    $('[data-xlsx]', block)?.addEventListener('click', () => {
      const fields = visibleFields(def).concat(def.fields.filter(f => f.hideInTable && !f.confidential));
      const rows = filteredRows(coll, def, st, opts.filter);
      const stamp = new Date().toISOString().slice(0, 10);
      downloadXLSX(\`\${def.short} \${stamp}.xlsx\`, def.short, [...(def.idLabel ? [def.idLabel] : []), ...fields.map(f => f.label)],
        rows.map(r => [...(def.idLabel ? [r.id] : []), ...fields.map(f => r[f.key])]));
      toast(\`Exported \${rows.length.toLocaleString()} row\${rows.length === 1 ? '' : 's'} to Excel\`);
    });
    const defaults = opts.defaults || {};
    $('[data-add]', block)?.addEventListener('click', () => editRow(coll, null, defaults));
    $('tbody', block)?.addEventListener('click', e => {
      const tr = e.target.closest('tr[data-id]'); if (!tr) return;
      editRow(coll, derive(coll).find(r => r.id === tr.dataset.id), defaults);
    });
    // Rows open with Enter as well as a click.
    $('tbody', block)?.addEventListener('keydown', e => {
      const tr = e.target.closest('tr[data-id]'); if (!tr || e.key !== 'Enter') return;
      editRow(coll, derive(coll).find(r => r.id === tr.dataset.id), defaults);
    });
  }
}

export function editRow(coll, row, defaults = {}) {
  const def = LOGS[coll];
  const fields = def.fields.filter(f => !f.confidential || store.can('confidential'));
  const canEdit = def.adminOnly ? store.can('admin') : store.can('edit');
  const today = new Date().toISOString().slice(0, 10);
  const init = row || { ...defaults, ...(def.dateKey && fields.find(f => f.key === def.dateKey)?.type === 'date' ? { [def.dateKey]: today } : {}) };
  const calcNote = row ? fields.filter(f => f.calc && row[f.key] !== '' && row[f.key] != null).map(f => \`\${f.label}: <b>\${esc(isISO(row[f.key]) ? row[f.key] : row[f.key])}</b>\`).join(' · ') : '';
  // OTIF: a Recordable Incident links to its Safety Incident / Near Miss Report (or says the required report is missing).
  const sfNote = coll === 'otif' && row && isRecordableType(row.type)
    ? (linkedReport(row.id) ? \`Safety Incident report: <a href="#/safety?open=\${encodeURIComponent(linkedReport(row.id).id)}">\${esc(linkedReport(row.id).id)}</a>\` : \`<b class="req">Required Safety Incident report missing</b> — <a href="#/safety?otif=\${encodeURIComponent(row.id)}">fill out the form now</a>\`)
    : coll === 'otif' ? 'Choosing Incident Type <b>Recordable Incident</b> asks for the Safety Incident / Near Miss Report when you save.' : '';
  // OTIF: email the incident to upper management (offered after saving a new entry; any time from here).
  const mgNote = coll === 'otif' ? (row
    ? \`<a href="#" data-otif-email="\${esc(row.id)}">✉ Email this incident to management</a>\${row.emailedAt ? \` <span class="muted small">— last emailed \${esc(new Date(row.emailedAt).toLocaleDateString('en-US'))}\${row.emailedTo ? ' to ' + esc(row.emailedTo) : ''}</span>\` : ''}\`
    : 'After you save, the incident report must be emailed to upper management (required).') : '';
  if (coll === 'otif') store.need(['incidents']).catch(() => {});
  openForm({
    title: row ? \`\${def.short}\${def.idLabel ? ' · ' + row.id : ''}\` : \`New \${def.short} entry\`,
    fields, values: init, readOnly: !canEdit,
    note: [def.help, calcNote, sfNote, mgNote].filter(Boolean).join('<br>'),
    onSave: async data => {
      const payload = { ...defaults, ...data };
      if (coll === 'otif' && !row) payload.loggedBy = store.user?.name || store.user?.email || '';
      let id = row?.id;
      if (row) await store.update(coll, row.id, payload); else id = await store.add(coll, payload);
      if (coll !== 'otif') return;
      const saved = { ...(row || {}), ...payload, id };
      // The management email is required for every OTIF entry: a new entry, or a saved one that was never emailed.
      // A Recordable Incident still needs its (mandatory) Safety Incident / Near Miss Report first; the email follows
      // once that report is saved.
      const mustEmail = !saved.emailedAt;
      const emailNow = () => setTimeout(() => promptOtifEmail(saved, { required: true }), 150);
      if (isRecordableType(payload.type) && !linkedReport(id)) setTimeout(() => promptSafetyReport(saved, mustEmail ? emailNow : undefined).catch(e => console.warn('Safety prompt skipped', e)), 80);
      else if (mustEmail) emailNow();
    },
    onDelete: row && (def.adminOnly ? store.can('admin') : store.can('delete')) ? () => store.remove(coll, row.id) : null,
  });
}

// ---------- Data tab insights (Labor, Customer Throughput, Employees) ----------
// Tiles and a chart that follow the table's search / year / facility filters.
const X = { dark: '#222b36', red: '#c0392b', tan: '#c0904d', blue: '#4d6f99', teal: '#1a9e7a', grey: '#9aa3b8' };
const legend = { position: 'bottom', labels: { boxWidth: 12, padding: 14 } };
const isEmp = r => ['HOURLY', 'EMPLOYEE', 'SALARIED'].includes(String(r.payType || '').toUpperCase()); // "Employee" = old name for Hourly
const sumBy = (rows, f) => rows.reduce((a, r) => a + (+f(r) || 0), 0);
const short = iso => (isISO(iso) ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}\` : iso);
const tilesRow = list => \`<div class="xl-tiles q" style="grid-template-columns:repeat(\${list.length}, minmax(0, 1fr))">\${list.join('')}</div>\`;
const frame = (title, id, h, aria) => \`<div class="xl-chart"><h4>\${title}</h4>\${chartBox(id, h, aria)}</div>\`;
const scope = st => [st.employee ? esc(String(st.employee).toUpperCase()) : '', st.year !== 'all' ? st.year : 'all years', st.facility ? \`building \${st.facility}\` : 'both buildings', st.q ? \`search "\${esc(st.q)}"\` : ''].filter(Boolean).join(' · ');

const INSIGHTS = {
  labor(rows, st) {
    const reg = sumBy(rows, r => r.reg), ot = sumBy(rows, r => r.ot), e = rows.filter(isEmp), eReg = sumBy(e, r => r.reg);
    const weeks = new Set(rows.map(r => r.weekEnding)).size, people = new Set(rows.map(r => r.employee)).size;
    return tilesRow([
      kpi('Regular hours', fmtNum(reg, 1), \`\${fmtNum(weeks)} weeks entered\`),
      kpi('OT hours', fmtNum(ot, 1), \`\${fmtNum(reg + ot, 1)} total hours\`),
      kpi('OT %', reg ? fmtPct(ot / reg, 1) : '-', 'OT hours ÷ regular hours', reg && ot / reg > 0.08 ? 'bad' : reg ? 'good' : ''),
      kpi('Employee OT %', eReg ? fmtPct(sumBy(e, r => r.ot) / eReg, 1) : '-', 'Employee + Salaried only'),
      kpi('People on the log', fmtNum(people), 'distinct names'),
    ]) + \`<div class="log-chart">\${frame('Weekly hours &amp; OT %', 'ch-log', 280, 'Weekly regular and OT hours stacked, with the OT percent line and the 8% threshold')}</div>\`;
  },
  throughput(rows, st) {
    const b = bb => rows.filter(r => String(r.building) === bb);
    const t49 = sumBy(b('6049'), r => r.total), t21 = sumBy(b('6021'), r => r.total);
    const weeks = new Set(rows.map(r => r.weekEnding)).size, custs = new Set(rows.map(r => r.customer)).size;
    const showB = st.facility ? [st.facility] : ['6049', '6021'];
    return tilesRow([
      ...(showB.includes('6049') ? [kpi('6049 throughput (pallets)', fmtNum(t49), \`In \${fmtNum(sumBy(b('6049'), r => r.inbound))} · Out \${fmtNum(sumBy(b('6049'), r => r.outbound))}\`)] : []),
      ...(showB.includes('6021') ? [kpi('6021 throughput (tons)', fmtNum(t21, 1), \`In \${fmtNum(sumBy(b('6021'), r => r.inbound), 1)} · Out \${fmtNum(sumBy(b('6021'), r => r.outbound), 1)}\`)] : []),
      kpi('Weeks entered', fmtNum(weeks), 'distinct week-ending dates'),
      kpi('Customers', fmtNum(custs), 'with volume in this view'),
    ]) + \`<div class="log-chart \${showB.length > 1 ? 'two' : ''}">\${showB.map(bb => frame(\`Weekly \${bb} throughput — \${bb === '6049' ? 'pallets' : 'tons'} in vs. out\`, 'ch-log-' + bb, 260, \`Weekly inbound and outbound volume for building \${bb}\`)).join('')}</div>\`;
  },
  employees(rows, st) {
    // Former employees and labor-only rows may be hidden from the table, so these counts use every record.
    const all = derive('employees');
    const active = all.filter(r => r.name && String(r.rosterStatus).toUpperCase() === 'ACTIVE').length;
    const former = all.filter(r => r.name && String(r.rosterStatus).toUpperCase() !== 'ACTIVE').length;
    const laborOnly = all.filter(r => !r.name).length, weekly = all.filter(r => String(r.laborActive).toUpperCase() === 'Y').length;
    return tilesRow([
      kpi('Active on roster', fmtNum(active), 'Roster Status = Active', 'good'),
      kpi('Not on current roster', fmtNum(former), st.roster === 'all' ? 'kept for history — shown in the table' : 'kept for history — pick "All employees" to see them'),
      kpi('Labor-only rows', fmtNum(laborOnly), laborOnly ? (st.showLaborOnly ? 'no roster name — shown in the table' : 'no roster name — hidden from the table') : 'every row is linked', laborOnly ? 'warn' : ''),
      kpi('On Weekly Entry', fmtNum(weekly), 'appear on the weekly labor form'),
    ]) + \`<div class="log-chart narrow">\${frame('Roster by home facility', 'ch-log', 200, 'Employees per home facility, split into active and not on current roster')}</div>\`;
  },
};

// ---------- Entry tab insights (OTIF, Attendance, Damage, Recognition, Disciplinary) ----------
const mk = iso => (isISO(iso) ? iso.slice(0, 7) : '');
const monLabel = k => { const [y, m] = k.split('-'); return \`\${['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][+m - 1]} \${y.slice(2)}\`; };
/** Up to 12 consecutive months ending with the latest entry (in the filtered view), oldest first — empty months included, so gaps show as zero. */
const monthsOf = (rows, key) => {
  const ks = rows.map(r => mk(r[key])).filter(Boolean).sort();
  if (!ks.length) return [];
  const out = [];
  let [y, m] = ks.at(-1).split('-').map(Number);
  while (out.length < 12) {
    const k = \`\${y}-\${String(m).padStart(2, '0')}\`;
    if (k < ks[0]) break;
    out.unshift(k);
    if (--m === 0) { m = 12; y--; }
  }
  return out;
};
const topOf = (rows, f) => { const m = new Map(); for (const r of rows) { const k = f(r); if (k) m.set(k, (m.get(k) || 0) + 1); } return [...m.entries()].sort((a, b) => b[1] - a[1])[0]; };
const TYPE_COLOR = { Failure: X.red, Mistake: '#e8a27c', 'Near Miss': X.tan, Performance: X.dark };
const SPARE = [X.blue, X.teal, X.grey, '#7d5ba6', '#d4ac0d'];
/** Monthly stacked bars: series = [[label, rowFilter, color]]. */
function monthlyStack(id, rows, key, series, yTitle, extra = []) {
  const months = monthsOf(rows, key);
  chart(id, {
    data: { labels: months.map(monLabel), datasets: [
      ...extra.map(e => e(months)),
      ...series.map(([label, f, color]) => ({ type: 'bar', label, data: months.map(m => rows.filter(r => mk(r[key]) === m && f(r)).length), backgroundColor: color, stack: 's', yAxisID: 'y', order: 2, borderRadius: 1 })),
    ] },
    options: { interaction: { mode: 'index', intersect: false },
      plugins: { legend, tooltip: { filter: t => t.parsed.y > 0 || t.dataset.type === 'line', callbacks: { footer: it => \`Total: \${it.filter(t => t.dataset.type !== 'line').reduce((a, t) => a + t.parsed.y, 0)}\` } } },
      scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: yTitle }, ticks: { precision: 0 } },
        ...(extra.length ? { y1: { position: 'right', beginAtZero: true, grid: { display: false }, title: { display: true, text: 'Est. $' }, ticks: { callback: v => '$' + v.toLocaleString() } } } : {}) } },
  });
}
/** Trend chart (monthly) with a ranked breakdown beside it. */
const monthlyFrame = (title, aria, side) => \`<div class="log-chart split">\${frame(title, 'ch-log', 280, aria)}\${side ? frame(side[0], 'ch-log-b', 280, side[1]) : ''}</div>\`;
/** Count rows per label, biggest first. */
const countBy = (rows, f) => { const m = new Map(); for (const r of rows) { const k = f(r); if (k) m.set(k, (m.get(k) || 0) + 1); } return [...m.entries()].sort((a, b) => b[1] - a[1]); };
/** Horizontal ranked bars (top n), value labels at the bar ends. */
function rankBars(id, entries, color, xTitle, n = 8) {
  const top = entries.slice(0, n);
  chart(id, {
    type: 'bar',
    data: { labels: top.map(e => e[0]), datasets: [{ label: xTitle, data: top.map(e => e[1]), backgroundColor: color, borderRadius: 3, barThickness: 'flex', maxBarThickness: 22 }] },
    options: { indexAxis: 'y', layout: { padding: { right: 28 } },
      plugins: { legend: { display: false }, tooltip: { callbacks: { label: t => \`\${xTitle}: \${t.parsed.x}\` } } },
      scales: { x: { beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: xTitle }, grid: { color: '#eef0f4' } }, y: { grid: { display: false }, ticks: { autoSkip: false, callback(v) { const l = this.getLabelForValue(v); return l.length > 22 ? l.slice(0, 21) + '…' : l; } } } } },
    plugins: [{ id: 'ends', afterDatasetsDraw(c) { const { ctx } = c; ctx.save(); ctx.font = '600 11px system-ui, sans-serif'; ctx.fillStyle = '#222b36'; ctx.textBaseline = 'middle';
      c.getDatasetMeta(0).data.forEach((b, i) => ctx.fillText(top[i][1], b.x + 6, b.y)); ctx.restore(); } }],
  });
}
const activeNames = () => new Set(store.rows('employees').filter(e => e.name && String(e.rosterStatus).toUpperCase() === 'ACTIVE').map(e => e.name.toUpperCase()));

Object.assign(INSIGHTS, {
  otif(rows) {
    const open = rows.filter(r => ['Open', 'In Progress'].includes(r.status)).length, top = topOf(rows, r => r.category);
    return tilesRow([
      kpi('Incidents', fmtNum(rows.length), \`\${fmtNum(rows.filter(r => r.type === 'Failure').length)} failures\`),
      kpi('Counted in accuracy', fmtNum(rows.filter(r => r.counts === 'Yes').length), 'types that lower Order Accuracy %'),
      kpi('Open / In progress', fmtNum(open), open ? 'need corrective action or closing' : 'all closed', open ? 'warn' : 'good'),
      kpi('Top category', top ? \`<span class="kv-text">\${esc(top[0])}</span>\` : '—', top ? \`\${top[1]} incidents\` : ''),
    ]) + monthlyFrame('Incidents by month &amp; type', 'Monthly OTIF incidents stacked by incident type', ['Top categories', 'OTIF incidents per category, most first']);
  },
  attendance(rows) {
    const live = rows.filter(r => r.dataCheck !== 'Duplicate'), c = t => live.filter(r => r.occurrence === t);
    const late = c('Tardy').filter(r => typeof r.minutesLate === 'number'), flagged = rows.filter(r => r.dataCheck).length;
    return tilesRow([
      kpi('Tardies', fmtNum(c('Tardy').length), late.length ? \`avg \${fmtNum(late.reduce((a, r) => a + r.minutesLate, 0) / late.length, 0)} min late\` : ''),
      kpi('Absences', fmtNum(c('Absent').length), \`\${fmtNum(c('Absent').filter(r => String(r.excused).toUpperCase() !== 'Y').length)} unexcused\`),
      kpi('Left early', fmtNum(c('Left Early').length), ''),
      kpi('Flagged entries', fmtNum(flagged), flagged ? 'duplicates or same-day entries to confirm' : 'none', flagged ? 'warn' : 'good'),
    ]) + monthlyFrame('Occurrences by month', 'Monthly tardies, absences and early departures stacked (duplicates excluded)', ['Most occurrences — active roster', 'Attendance occurrences per active employee, most first']);
  },
  damage(rows) {
    const piper = rows.filter(r => r.piperCaused === 'Yes').length, open = rows.filter(r => ['Open', 'Filed'].includes(r.claimStatus)).length;
    return tilesRow([
      kpi('Damage incidents', fmtNum(rows.length), \`6049: \${rows.filter(r => String(r.facility) === '6049').length} · 6021: \${rows.filter(r => String(r.facility) === '6021').length}\`),
      kpi('Piper-caused', rows.length ? fmtPct(piper / rows.length, 0) : '-', \`\${fmtNum(piper)} incidents\`),
      kpi('Est. $ damage', '$' + fmtNum(sumBy(rows, r => r.value)), \`\${fmtNum(sumBy(rows, r => r.qty))} units damaged\`),
      kpi('Open claims', fmtNum(open), 'Claim Status Open or Filed', open ? 'warn' : ''),
    ]) + monthlyFrame('Damage incidents by month &amp; building, with est. $', 'Monthly damage incidents stacked by building with the estimated dollar line', ['Incidents by cause', 'Damage incidents per cause, most first']);
  },
  recognition(rows) {
    const people = new Set(rows.map(r => r.recipient)).size, top = topOf(rows, r => r.award);
    return tilesRow([
      kpi('Awards', fmtNum(rows.length), \`\${fmtNum(people)} people recognized\`),
      kpi('Most given', top ? \`<span class="kv-text">\${esc(top[0])}</span>\` : '—', top ? \`\${top[1]} awards\` : ''),
      kpi('Latest month', rows.length ? monLabel(monthsOf(rows, 'month').at(-1) || '') : '—', ''),
    ]) + monthlyFrame('Awards by month &amp; type', 'Monthly awards stacked by award type', ['Most recognized — active roster', 'Awards per active employee, most first']);
  },
  discipline(rows) {
    const active = rows.filter(r => r.status === 'Active').length, top = topOf(rows, r => r.category);
    return tilesRow([
      kpi('Actions logged', fmtNum(rows.length), ''),
      kpi('Active now', fmtNum(active), 'within the active period', active ? 'warn' : ''),
      kpi('Top category', top ? \`<span class="kv-text">\${esc(top[0])}</span>\` : '—', top ? \`\${top[1]} actions\` : ''),
    ]) + monthlyFrame('Actions by month &amp; level', 'Monthly disciplinary actions stacked by action level', ['Actions by category', 'Disciplinary actions per category, most first']);
  },
});

function drawInsights(coll, rows, st) {
  if (coll === 'otif') {
    const types = [...new Set([...store.settings.incidentTypes.map(t => t.name), ...rows.map(r => r.type).filter(Boolean)])];
    monthlyStack('ch-log', rows, 'date', types.map((t, i) => [t, r => r.type === t, TYPE_COLOR[t] || SPARE[i % SPARE.length]]), 'Incidents');
    return rankBars('ch-log-b', countBy(rows, r => r.category), X.red, 'Incidents');
  }
  if (coll === 'attendance') {
    const live = rows.filter(r => r.dataCheck !== 'Duplicate'), act = activeNames();
    monthlyStack('ch-log', live, 'date', [['Tardies', r => r.occurrence === 'Tardy', X.tan], ['Absences', r => r.occurrence === 'Absent', X.red], ['Left early', r => r.occurrence === 'Left Early', X.dark]], 'Occurrences');
    return rankBars('ch-log-b', countBy(live, r => (act.has(String(r.employee).toUpperCase()) ? r.employee : '')), X.red, 'Occurrences', 10);
  }
  if (coll === 'damage') {
    const dollars = months => ({ type: 'line', label: 'Est. $', data: months.map(m => sumBy(rows.filter(r => mk(r.date) === m), r => r.value) || null), borderColor: X.tan, backgroundColor: X.tan, pointBackgroundColor: '#fff', pointBorderColor: X.tan, pointRadius: 4, pointBorderWidth: 2, yAxisID: 'y1', order: 0, spanGaps: true });
    monthlyStack('ch-log', rows, 'date', [['6049', r => String(r.facility) === '6049', X.dark], ['6021', r => String(r.facility) === '6021', X.red]], 'Incidents', [dollars]);
    return rankBars('ch-log-b', countBy(rows, r => r.cause), X.dark, 'Incidents');
  }
  if (coll === 'recognition') {
    const awards = [...new Set([...(store.settings.lists.awardTypes || []), ...rows.map(r => r.award).filter(Boolean)])], act = activeNames();
    monthlyStack('ch-log', rows, 'month', awards.map((a, i) => [a, r => r.award === a, [X.teal, X.tan, X.blue, X.dark, X.grey][i % 5]]), 'Awards');
    return rankBars('ch-log-b', countBy(rows, r => (act.has(String(r.recipient).toUpperCase()) ? r.recipient : '')), X.teal, 'Awards', 10);
  }
  if (coll === 'discipline') {
    // Colours run light → dark with severity, in the order of the Settings list (coaching … termination).
    const levels = [...new Set([...(store.settings.lists.disciplineActions || []), ...rows.map(r => r.action).filter(Boolean)])];
    const SEV = ['#e6d3b0', X.tan, '#e8a27c', X.red, '#8e2a20', X.dark, X.grey];
    monthlyStack('ch-log', rows, 'date', levels.map((a, i) => [a, r => r.action === a, SEV[i % SEV.length]]), 'Actions');
    return rankBars('ch-log-b', countBy(rows, r => r.category), X.tan, 'Actions');
  }
  if (coll === 'labor') {
    const weeks = [...new Set(rows.map(r => r.weekEnding))].filter(isISO).sort().slice(-52);
    const w = weeks.map(wk => { const rs = rows.filter(r => r.weekEnding === wk); const reg = sumBy(rs, r => r.reg), ot = sumBy(rs, r => r.ot); return { wk, reg, ot, pct: reg ? +(ot / reg * 100).toFixed(1) : null }; });
    chart('ch-log', {
      data: { labels: w.map(x => short(x.wk)), datasets: [
        { type: 'line', label: 'OT %', data: w.map(x => x.pct), borderColor: X.tan, backgroundColor: X.tan, pointBackgroundColor: '#fff', pointBorderColor: X.tan, pointRadius: 3, pointBorderWidth: 2, borderWidth: 2.5, yAxisID: 'y1', order: 0, spanGaps: true },
        { type: 'line', label: '8% threshold', data: w.map(() => 8), borderColor: X.red, borderDash: [2, 3], pointRadius: 0, borderWidth: 1.5, yAxisID: 'y1', order: 1 },
        { type: 'bar', label: 'Regular hours', data: w.map(x => +x.reg.toFixed(1)), backgroundColor: X.dark, stack: 'h', yAxisID: 'y', order: 2 },
        { type: 'bar', label: 'OT hours', data: w.map(x => +x.ot.toFixed(1)), backgroundColor: X.red, stack: 'h', yAxisID: 'y', order: 2 },
      ] },
      options: { interaction: { mode: 'index', intersect: false }, plugins: { legend, tooltip: { callbacks: { title: it => \`Week ending \${w[it[0].dataIndex].wk}\`, label: t => \`\${t.dataset.label}: \${t.dataset.yAxisID === 'y1' ? t.parsed.y + '%' : t.parsed.y.toLocaleString()}\` } } },
        scales: { x: { stacked: true, grid: { display: false }, title: { display: true, text: weeks.length >= 52 ? 'Week ending (latest 52 weeks)' : 'Week ending' }, ticks: { maxRotation: 0, autoSkip: true } },
          y: { stacked: true, beginAtZero: true, title: { display: true, text: 'Hours' }, ticks: { callback: v => v.toLocaleString() } },
          y1: { position: 'right', beginAtZero: true, suggestedMax: 14, grid: { display: false }, title: { display: true, text: 'OT %' }, ticks: { callback: v => v + '%' } } } },
    });
  } else if (coll === 'throughput') {
    for (const bb of st.facility ? [st.facility] : ['6049', '6021']) {
      const rs = rows.filter(r => String(r.building) === bb), weeks = [...new Set(rs.map(r => r.weekEnding))].filter(isISO).sort().slice(-52);
      const unit = bb === '6049' ? 'pallets' : 'tons';
      chart('ch-log-' + bb, {
        type: 'bar',
        data: { labels: weeks.map(short), datasets: [
          { label: 'Inbound', data: weeks.map(wk => sumBy(rs.filter(r => r.weekEnding === wk), r => r.inbound)), backgroundColor: X.blue, stack: 't' },
          { label: 'Outbound', data: weeks.map(wk => sumBy(rs.filter(r => r.weekEnding === wk), r => r.outbound)), backgroundColor: X.tan, stack: 't' },
        ] },
        options: { plugins: { legend, tooltip: { mode: 'index', callbacks: { title: it => \`Week ending \${weeks[it[0].dataIndex]}\`, footer: it => \`Total: \${fmtNum(it.reduce((a, t) => a + t.parsed.y, 0), bb === '6021' ? 1 : 0)} \${unit}\` } } },
          scales: { x: { stacked: true, grid: { display: false }, ticks: { maxRotation: 0, autoSkip: true } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: unit[0].toUpperCase() + unit.slice(1) }, ticks: { callback: v => v.toLocaleString() } } } },
      });
    }
  } else if (coll === 'employees') {
    const facs = [...new Set(rows.map(r => r.homeFacility || ''))].sort((a, b) => (a || 'zz').localeCompare(b || 'zz'));
    const count = (f, act) => rows.filter(r => (r.homeFacility || '') === f && (String(r.rosterStatus).toUpperCase() === 'ACTIVE') === act && (act || r.name)).length;
    chart('ch-log', {
      type: 'bar',
      data: { labels: facs.map(f => f || 'No facility'), datasets: [
        { label: 'Active', data: facs.map(f => count(f, true)), backgroundColor: X.teal, stack: 'e', borderRadius: 2 },
        { label: 'Not on current roster', data: facs.map(f => count(f, false)), backgroundColor: X.grey, stack: 'e', borderRadius: 2 },
      ] },
      options: { indexAxis: 'y', plugins: { legend, tooltip: { mode: 'index' } }, scales: { x: { stacked: true, beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: 'Employees' } }, y: { stacked: true, grid: { display: false } } } },
    });
  }
}

// Employees page: shows Active employees unless "All employees" is picked; labor-only records (no Roster Name)
// are hidden unless "Show labor-only records" is ticked. Nothing is removed — Weekly Entry and the Labor log still use them.
const pageFilter = (coll, st) => (coll !== 'employees' ? undefined
  : r => (r.name ? st.roster === 'all' || norm(r.rosterStatus) === 'ACTIVE' : !!st.showLaborOnly));

// Route view: #/log/<coll>
export default {
  // MHE logs calculate from each other (register ← hours / service), so they load together.
  needs: p => (String(p.coll).startsWith('mhe') ? ['mheAssets', 'mheHours', 'mheService', 'mheOperators', 'mheExceptions', 'mheConfig', 'employees'] : [p.coll, 'employees']),
  render(p) {
    const def = LOGS[p.coll];
    if (!def) return page('Not found');
    if (def.confidential && !store.can('confidential')) return page(def.title, 'This log is restricted to managers and HR.');
    const st = logState(p.coll);
    if (p.query.ids) st.ids = p.query.ids.split(',');
    // ?employee=NAME (from the Attendance Scorecard): that person's full history, every year, newest first.
    // The filter lives in the address, so opening the log from the menu shows everyone again.
    const emp = p.query.employee || '';
    if (emp !== st.employee) Object.assign(st, { employee: emp }, emp ? { year: 'all', q: '', facility: '', sort: null, limit: 200 } : {});
    const filter = pageFilter(p.coll, st);
    const rows = filteredRows(p.coll, def, st, filter);
    const laborOnly = p.coll === 'employees' ? derive('employees').filter(r => !r.name).length : 0;
    const head = \`<div class="xl-dash-head log-head">
        <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;\${esc(def.title)}</h1><p>\${esc(def.help || '')} Click a row (or press Enter on it) to view or edit it.</p></div>
        <div class="xl-meta"><b>Rows shown:</b><span class="xl-year">\${fmtNum(rows.length)}</span><b>Showing</b><span class="xl-thru">\${scope(st)}</span>
          \${p.coll === 'employees' ? \`<label class="inline small">Show <select data-roster aria-label="Which employees to show">
            <option value="active"\${st.roster !== 'all' ? ' selected' : ''}>Active employees</option>
            <option value="all"\${st.roster === 'all' ? ' selected' : ''}>All employees</option></select></label>\` : ''}
          \${laborOnly ? \`<label class="inline small" title="People on Weekly Entry / the Labor log with no Roster Name (e.g. salaried staff, casual labor). Hidden here only — nothing is deleted."><input type="checkbox" data-show-labor \${st.showLaborOnly ? 'checked' : ''}> Show labor-only records (\${laborOnly})</label>\` : ''}
          \${p.coll === 'discipline' && store.can('edit') ? '<span class="sp"></span><button type="button" class="btn primary" data-writeup>✎ New write-up</button>' : ''}
          \${p.coll === 'employees' && store.can('admin') ? '<span class="sp"></span><button type="button" class="btn primary" data-import-ids title="Load the HR system\\'s Employee Information export (.csv): IDs, name spelling, missing people">⬆ Sync with HR file</button>' : ''}</div>
        \${INSIGHTS[p.coll] ? \`<div class="log-insights">\${INSIGHTS[p.coll](rows, st)}</div>\` : ''}
      </div>\`;
    return \`<div class="log-xl">\${head}<section class="card log-card">\${logBlock(p.coll, { filter })}</section></div>\`;
  },
  after(root, p, rerender) {
    const filter = pageFilter(p.coll, logState(p.coll));
    bindLogs(root, rerender, { filter });
    $('[data-show-labor]', root)?.addEventListener('change', e => { logState(p.coll).showLaborOnly = e.target.checked; rerender(); });
    $('[data-roster]', root)?.addEventListener('change', e => { logState(p.coll).roster = e.target.value; rerender(); });
    $('[data-writeup]', root)?.addEventListener('click', () => openWriteUp(rerender));
    $('[data-import-ids]', root)?.addEventListener('click', () => importEmployeeIds(rerender));
    if (INSIGHTS[p.coll] && LOGS[p.coll]) { const st = logState(p.coll); drawInsights(p.coll, filteredRows(p.coll, LOGS[p.coll], st, filter), st); }
    if (p.query.add && store.can('edit')) {
      history.replaceState(null, '', location.hash.replace(/[?&]add=1/, ''));
      editRow(p.coll, null);
    }
  },
};`]);

// ===================== views/mhe.js =====================
ATL_SRC.push(['@atl/views/mhe.js', 0, `// MHE Fleet (#/mhe): dashboard laid out like the Rail Car Dashboard, plus Fleet Register, Hours & Service,
// Operators (certifications and their prerequisites) and Exceptions tabs, and the workbook import.
import { store } from '@atl/store.js';
import { esc, fmtNum, fmtPct, fmtMoney, fmtDate, isISO, toast, $, $$, todayISO, norm } from '@atl/util.js';
import { chart, chartBox, kpi } from '@atl/ui.js';
import { logBlock, bindLogs, logState, editRow } from '@atl/views/logs.js';
import { derive } from '@atl/calc.js';
import { COLLS, SITES, REGION, SITE_BLDG, config, fleetStats, weeklyHours, operatorPeople, serviceRows, hoursRows, isTruck, readRegister, SERVICE_CATS, planImport, applyImport, planTableHtml } from '@atl/mhe.js';

const st = { tab: 'dashboard', site: '' };
const TABS = [['dashboard', 'Dashboard'], ['register', 'Fleet register'], ['hours', 'Hours & service'], ['operators', 'Operators'], ['exceptions', 'Exceptions & pairings'], ['import', 'Import / settings']];
const SITE_COLORS = ['#222b36', '#c0392b', '#c0904d', '#4d6f99', '#1a9e7a', '#7d5ba6', '#9aa3b8'];
const legend = { position: 'bottom', labels: { boxWidth: 12, padding: 14 } };
const dash = v => (v ? fmtNum(v) : '-');
const us = iso => (isISO(iso) ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(2, 4)}\` : esc(iso || ''));
const pill = (text, tone) => \`<span class="pill \${tone}">\${esc(text)}</span>\`;
const certTone = s => (s === 'Expired' ? 'bad' : s === 'Current' ? 'good' : 'warn');
const pmTone = s => (s === 'Overdue' ? 'bad' : s === 'Due in 14 Days' ? 'warn' : s === 'Current' ? 'good' : 'neutral');
const sevTone = s => (s === 'Critical' || s === 'High' ? 'bad' : s === 'Medium' ? 'warn' : 'info');
const siteLabel = s => (SITE_BLDG[s] ? \`\${s} (\${SITE_BLDG[s]})\` : s);
let parsed = null, busy = false;

const head = (title, desc, meta) => \`<div class="xl-dash-head rail-head">
    <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;\${title}</h1><p>\${desc}</p></div>
    <div class="xl-meta">\${meta}<span class="xl-meta-title">MHE Fleet</span></div></div>\`;
const chips = () => \`<nav class="rail-chips" aria-label="MHE Fleet pages"><span>MHE Fleet</span>
    \${TABS.filter(([k]) => k !== 'import' || store.can('edit')).map(([k, l]) => \`<a class="rchip\${st.tab === k ? ' on' : ''}" href="#/mhe?tab=\${k}"\${st.tab === k ? ' aria-current="page"' : ''}>\${l}</a>\`).join('')}</nav>\`;
const rsSection = (title, body) => \`<section class="card rail-perf"><div class="rs-title">\${title}</div>\${body}</section>\`;
const cell = (label, value, note, cls = '') => \`<div class="rs-cell"><div class="rs-label">\${label}</div><div class="rs-value \${cls}">\${value}</div><div class="rs-note">\${note}</div></div>\`;
const strip = cells => \`<div class="rail-strip">\${cells.join('')}</div>\`;
const mheChart = (title, id, h, aria, cls = '') => \`<div class="rs-chart \${cls}"><h4>\${title}</h4>\${chartBox(id, h, aria)}</div>\`;
const siteMatch = r => !st.site || r.site === st.site;
const opMatch = o => !st.site || o.building === st.site || (o.building === 'Both (ATL)' && REGION[st.site] === 'Atlanta');

// ---------------------------------------------------------------- dashboard
function topStrip(S) {
  const clamp = S.trucks.filter(a => /clamp truck/i.test(a.family || '') && !/bale/i.test(a.family || '')).length;
  return strip([
    cell('Total assets', fmtNum(S.total), \`\${fmtNum(S.attach)} attachments · \${fmtNum(S.facility)} facility\`),
    cell('Powered trucks', fmtNum(S.trucks.length), \`\${fmtNum(clamp)} clamp · \${fmtNum(S.trucks.length - clamp)} other\`),
    cell('Trucks owned outright', S.owned === '' ? 'n/a' : fmtPct(S.owned, 0), 'of powered trucks'),
    cell('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days · \${fmtNum(S.pmNone)} trucks no PM\`, S.pmOverdue.length ? 'down' : ''),
    cell('Open service items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days open\` : 'nothing waiting', S.open.length ? 'warn' : ''),
    cell(\`Service spend \${todayISO().slice(0, 4)}\`, fmtMoney(S.spendYTD), 'invoices, year to date'),
    cell('Avg hours / truck / wk', S.avgHrs === '' ? 'n/a' : fmtNum(S.avgHrs, 1), \`last 8 OK weeks · \${fmtNum(S.hrsTrucks)} trucks reporting\`),
    cell('Operators certified', fmtNum(new Set(S.opActive.map(o => norm(o.employee))).size), \`\${fmtNum(S.opExpired.length)} expired · \${fmtNum(S.opExpiring.length)} expiring\`, S.opExpired.length ? 'warn' : ''),
    cell('Open critical / high', fmtNum(S.critHigh), \`\${fmtNum(S.openExc.length)} open exceptions · \${fmtNum(S.needAction)} records not verified\`, S.critHigh ? 'warn' : ''),
  ]);
}

function watchlist(S) {
  const pm = [...S.pmOverdue, ...S.pmDue].filter(isTruck).sort((a, b) => String(a.nextPM).localeCompare(String(b.nextPM)));
  const pmRows = pm.slice(0, 10).map(a => \`<tr><td class="cust"><b>\${esc(a.assetId)}</b></td><td class="cust">\${esc(a.site)}</td><td class="cust">\${esc(a.family || a.type || '')}</td><td>\${us(a.lastPM)}</td><td>\${us(a.nextPM)}</td><td>\${pill(a.pmStatus, pmTone(a.pmStatus))}</td></tr>\`).join('');
  const openRows = S.open.slice(0, 10).map(s => \`<tr><td class="cust"><b>\${esc(s.assetId || s.serial)}</b></td><td class="cust">\${esc(s.site)}</td><td class="cust">\${esc(s.category)}</td><td class="cust clip" title="\${esc(s.performed)}"><div class="clip-in">\${esc(s.performed || '')}</div></td><td>\${us(s.serviceDate)}</td><td><span class="pill \${s.daysOpen > 30 ? 'bad' : 'warn'}">\${fmtNum(s.daysOpen)} days</span></td></tr>\`).join('');
  const certs = [...S.opExpired, ...S.opExpiring, ...S.opCheck].sort((a, b) => (a.daysToExpiry === '' ? 1e9 : a.daysToExpiry) - (b.daysToExpiry === '' ? 1e9 : b.daysToExpiry));
  const certRows = certs.slice(0, 12).map(o => \`<tr><td class="cust"><b>\${esc(o.employee)}</b></td><td class="cust">\${esc(o.equipment)}</td><td class="cust">\${esc(o.building)}</td><td>\${us(o.expires)}</td><td>\${pill(o.status === 'Expired' ? \`Expired \${fmtNum(-o.daysToExpiry)} d\` : o.status, certTone(o.status))}</td></tr>\`).join('');
  return \`<div class="rs-pair rs-risk">
    \${rsSection(\`Maintenance watchlist <span class="pill \${pm.length + S.open.length ? 'bad' : 'good'}">\${pm.length + S.open.length ? \`\${pm.length} PM · \${S.open.length} open\` : 'All clear'}</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Truck</th><th class="cust">Site</th><th class="cust">Equipment</th><th>Last PM</th><th>Next PM due</th><th>PM status</th></tr></thead>
      <tbody>\${pmRows || '<tr><td colspan="6">No PMs overdue or due in the next 14 days.</td></tr>'}</tbody></table></div>
      <div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Asset</th><th class="cust">Site</th><th class="cust">Category</th><th class="cust">Service performed</th><th>Opened</th><th>Open</th></tr></thead>
      <tbody>\${openRows || '<tr><td colspan="6">No open service items.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">PM interval \${fmtNum(config().pmInterval)} days from the last Preventive Maintenance in the Service Log. \${S.pmNone ? \`\${fmtNum(S.pmNone)} powered trucks have no PM on record yet (Not Scheduled).\` : ''} <a href="#/mhe?tab=hours">Hours &amp; service ›</a></p>\`)}
    \${rsSection(\`Operator certifications needing action <span class="pill \${certs.length ? 'bad' : 'good'}">\${certs.length ? \`\${certs.length} cert\${certs.length === 1 ? '' : 's'}\` : 'None'}</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Operator</th><th class="cust">Equipment</th><th class="cust">Building</th><th>Expires</th><th>Status</th></tr></thead>
      <tbody>\${certRows || '<tr><td colspan="5">Every certification is current.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">OSHA 1910.178(l): an operator is re-evaluated at least every 3 years. Expiring = within \${fmtNum(config().expiringDays)} days.\${certs.length > 12 ? \` \${certs.length - 12} more on the Operators tab.\` : ''} <a href="#/mhe?tab=operators">Operators ›</a></p>\`)}
  </div>\`;
}

function compositionTable(S) {
  const rows = S.bySite, tot = k => rows.reduce((t, r) => t + r[k], 0);
  const maxT = Math.max(1, ...rows.map(r => r.total));
  const row = (r, isTotal) => \`<tr\${isTotal ? ' class="total"' : ''}><td class="cust">\${isTotal ? 'Total' : \`<a href="#/mhe?tab=register&site=\${encodeURIComponent(r.site)}">\${esc(siteLabel(r.site))}</a>\`}</td><td class="cust">\${isTotal ? '' : esc(r.region)}</td>
    <td class="num">\${dash(r.clamp)}</td><td class="num">\${dash(r.other)}</td><td class="num"><b>\${dash(r.trucks)}</b></td><td class="num">\${dash(r.attach)}</td><td class="num">\${dash(r.facility)}</td>
    <td class="num bar">\${isTotal ? '' : \`<i style="width:\${(r.total / maxT) * 100}%"></i>\`}<span>\${fmtNum(r.total)}</span></td>
    <td class="num">\${dash(r.owned)}</td><td class="num">\${dash(r.lto)}</td><td class="num \${r.unconf && !isTotal ? 'hl' : ''}">\${dash(r.unconf)}</td><td class="num">\${dash(r.rental)}</td><td class="num \${r.notRec && !isTotal ? 'hl' : ''}">\${dash(r.notRec)}</td>
    <td class="num \${r.issues && !isTotal ? 'hl' : ''}">\${dash(r.issues)}</td><td class="num \${r.pmOverdue ? 'neg' : ''}">\${dash(r.pmOverdue)}</td><td class="num">\${r.leaseSpend ? fmtMoney(r.leaseSpend) : '-'}</td></tr>\`;
  const T = { clamp: tot('clamp'), other: tot('other'), trucks: tot('trucks'), attach: tot('attach'), facility: tot('facility'), total: tot('total'), owned: tot('owned'), lto: tot('lto'), unconf: tot('unconf'), rental: tot('rental'), notRec: tot('notRec'), issues: tot('issues'), pmOverdue: tot('pmOverdue'), leaseSpend: tot('leaseSpend') };
  return rsSection('Fleet composition &amp; ownership by site', \`<div class="table-wrap"><table class="perf">
    <thead><tr><th class="cust">Site</th><th class="cust">Region</th><th>Clamp<br>Trucks</th><th>Other<br>Trucks</th><th>Total<br>Trucks</th><th>Attach-<br>ments</th><th>Facility<br>Equip.</th><th>Total<br>Assets</th>
      <th>Owned</th><th>Lease-to-<br>Own</th><th>Owned/LTO<br>Unconfirmed</th><th>Rental</th><th>Not<br>Recorded</th><th>Records<br>w/ Issues</th><th>PM<br>Overdue</th><th>Monthly<br>Lease $</th></tr></thead>
    <tbody>\${rows.map(r => row(r)).join('')}\${row(T, true)}</tbody></table></div>
    <p class="rs-foot">Ownership is for every asset at the site (trucks, attachments, facility). Records w/ Issues = Data Status other than Verified. Monthly lease $ counts active leases with a payment on file.</p>\`);
}

function mixTable(S) {
  const regions = ['Atlanta', 'Indiana', 'Ohio'];
  return rsSection('Equipment mix by region', \`<div class="table-wrap"><table class="perf">
    <thead><tr><th class="cust">Equipment family</th><th class="cust">Class</th>\${regions.map(r => \`<th>\${r}</th>\`).join('')}<th>Total</th></tr></thead>
    <tbody>\${S.mix.map(m => \`<tr><td class="cust">\${esc(m.family)}</td><td class="cust">\${esc(m.cls)}</td>\${regions.map(r => \`<td class="num">\${dash(m[r])}</td>\`).join('')}<td class="num"><b>\${fmtNum(m.total)}</b></td></tr>\`).join('')}
      <tr class="total"><td class="cust">Total</td><td></td>\${regions.map(r => \`<td class="num">\${dash(S.mix.reduce((t, m) => t + m[r], 0))}</td>\`).join('')}<td class="num">\${fmtNum(S.total)}</td></tr></tbody></table></div>\`);
}

function exceptionsAndLeases(S) {
  const sev = ['Critical', 'High', 'Medium', 'Low'];
  const top = [...S.openExc].sort((a, b) => sev.indexOf(a.severity) - sev.indexOf(b.severity) || String(a.id).localeCompare(String(b.id), undefined, { numeric: true })).slice(0, 8);
  const leased = S.A.filter(a => a.leaseStatus);
  return \`<div class="rs-pair">
    \${rsSection(\`Top priorities — open exceptions <span class="pill \${S.critHigh ? 'bad' : 'good'}">\${fmtNum(S.openExc.length)} open</span>\`, \`<div class="mhe-sev">\${sev.map(s => { const n = S.openExc.filter(x => x.severity === s).length; return \`<div class="mhe-sev-cell \${sevTone(s)}"><b>\${fmtNum(n)}</b><span>\${s}</span></div>\`; }).join('')}</div>
      <div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">ID</th><th>Severity</th><th class="cust">Site</th><th class="cust">Issue</th><th class="cust">Owner</th></tr></thead>
      <tbody>\${top.map(x => \`<tr><td class="cust"><b>\${esc(x.id)}</b></td><td>\${pill(x.severity, sevTone(x.severity))}</td><td class="cust">\${esc(x.site)}</td><td class="cust clip" title="\${esc(x.issue)}"><div class="clip-in">\${esc(x.issue)}</div></td><td class="cust">\${esc(x.owner || '')}</td></tr>\`).join('') || '<tr><td colspan="5">No open exceptions.</td></tr>'}</tbody></table></div>
      <p class="rs-foot"><a href="#/mhe?tab=exceptions">All exceptions ›</a></p>\`)}
    \${rsSection('Lease exposure', \`<div class="mhe-sev">
        <div class="mhe-sev-cell info"><b>\${fmtNum(S.leases.length)}</b><span>Active leases</span></div>
        <div class="mhe-sev-cell neutral"><b>\${fmtMoney(S.leaseMonthly)}</b><span>Monthly payments</span></div>
        <div class="mhe-sev-cell neutral"><b>\${fmtMoney(S.leaseRemaining)}</b><span>Remaining obligation</span></div>
        <div class="mhe-sev-cell \${S.leaseMissing ? 'warn' : 'good'}"><b>\${fmtNum(S.leaseMissing)}</b><span>Missing lease data</span></div></div>
      <div class="table-wrap"><table class="perf"><thead><tr><th class="cust">Status</th><th>Units</th><th>Monthly $</th><th>Remaining $</th></tr></thead>
      <tbody>\${['Active', 'Ending in 90 Days', 'Expired - Confirm Buyout', 'Not Started', 'Missing Data'].map(s => { const u = leased.filter(a => a.leaseStatus === s); return u.length ? \`<tr><td class="cust">\${pill(s, s === 'Active' ? 'good' : s === 'Missing Data' || s === 'Ending in 90 Days' ? 'warn' : s === 'Not Started' ? 'info' : 'bad')}</td><td class="num">\${fmtNum(u.length)}</td><td class="num">\${fmtMoney(u.reduce((t, a) => t + (+a.leasePayment || 0), 0))}</td><td class="num">\${fmtMoney(u.reduce((t, a) => t + (+a.leaseRemaining || 0), 0))}</td></tr>\` : ''; }).join('') || '<tr><td colspan="4">No leased units.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">Lease-to-Own, Rental and Unconfirmed units need lessor, contract, start date, term and payment (Fleet register ▸ open a unit). Remaining = payments left + buyout until the lease ends.</p>\`)}
  </div>\`;
}

const trends = () => rsSection('Trends', \`<div class="rs-charts">
    \${mheChart('Truck hours by week and site (OK readings)', 'ch-mhe-hours', 280, 'Hours used per week, stacked by site', 'wide')}
    \${mheChart('Fleet by site and ownership', 'ch-mhe-own', 280, 'Assets per site stacked by ownership')}
    \${mheChart('Service spend by month and category', 'ch-mhe-spend', 280, 'Invoice dollars per month stacked by service category')}
  </div>\`);

function drawDashboard(S) {
  const W = weeklyHours(12, st.site);
  chart('ch-mhe-hours', { type: 'bar', data: { labels: W.weeks.map(w => \`\${+w.slice(5, 7)}/\${+w.slice(8, 10)}\`), datasets: W.data.map(d => ({ label: d.site, data: d.values, backgroundColor: SITE_COLORS[Math.max(0, SITES.indexOf(d.site)) % SITE_COLORS.length], stack: 'h', borderRadius: 1 })) },
    options: { plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.y > 0, callbacks: { label: t => \`\${t.dataset.label}: \${fmtNum(t.parsed.y, 1)} hrs\`, footer: it => \`Total \${fmtNum(it.reduce((a, t) => a + t.parsed.y, 0), 1)} hrs\` } } },
      scales: { x: { stacked: true, grid: { display: false }, title: { display: true, text: 'Week ending' } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: 'Hours used' } } } } });
  const own = [['Owned', '#1f4a85'], ['Lease-to-Own', '#5f84b8'], ['Owned/LTO - Unconfirmed', '#c0904d'], ['Rental', '#9db3d3'], ['Not Recorded', '#c0392b']];
  chart('ch-mhe-own', { type: 'bar', data: { labels: S.bySite.map(r => r.site), datasets: own.map(([o, c]) => ({ label: o, data: S.bySite.map(r => S.A.filter(a => a.site === r.site && (o === 'Not Recorded' ? !a.ownership || a.ownership === o : a.ownership === o)).length || null), backgroundColor: c, stack: 'o' })) },
    options: { indexAxis: 'y', plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.x > 0 } }, scales: { x: { stacked: true, beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: 'Assets' } }, y: { stacked: true, grid: { display: false } } } } });
  const svc = serviceRows().filter(siteMatch).filter(s => isISO(s.serviceDate) && +s.amount);
  const months = [...new Set(svc.map(s => s.serviceDate.slice(0, 7)))].sort().slice(-12);
  const cats = SERVICE_CATS.filter(c => svc.some(s => s.category === c));
  chart('ch-mhe-spend', { type: 'bar', data: { labels: months.map(m => new Date(m + '-01T00:00:00Z').toLocaleString('en-US', { month: 'short', year: '2-digit', timeZone: 'UTC' })), datasets: cats.map((c, i) => ({ label: c, data: months.map(m => svc.filter(s => s.category === c && s.serviceDate.startsWith(m)).reduce((t, s) => t + +s.amount, 0) || null), backgroundColor: ['#1f4a85', '#c0392b', '#c0904d', '#1a9e7a', '#7d5ba6', '#9aa3b8'][i % 6], stack: 's' })) },
    options: { plugins: { legend, tooltip: { mode: 'index', filter: t => t.parsed.y > 0, callbacks: { label: t => \`\${t.dataset.label}: \${fmtMoney(t.parsed.y)}\`, footer: it => \`Total \${fmtMoney(it.reduce((a, t) => a + t.parsed.y, 0))}\` } } },
      scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, ticks: { callback: v => fmtMoney(v) }, title: { display: true, text: 'Invoice $' } } } } });
}

// ---------------------------------------------------------------- tabs
const tiles = list => \`<div class="xl-tiles q" style="grid-template-columns:repeat(\${list.length}, minmax(0, 1fr))">\${list.join('')}</div>\`;
const tile = (label, value, note = '', tone = '') => kpi(label, value, note, tone);

function registerTab(S) {
  return \`<section class="card rail-sum"><div class="rs-title">Fleet register\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Assets', fmtNum(S.total), \`\${fmtNum(S.trucks.length)} trucks · \${fmtNum(S.attach)} attachments\`), tile('Verified records', fmtNum(S.total - S.needAction), \`\${fmtNum(S.needAction)} conflict / incomplete / unverified\`, S.needAction ? 'warn' : 'good'),
        tile('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days\`, S.pmOverdue.length ? 'bad' : 'good'), tile('Open service items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days\` : '', S.open.length ? 'warn' : ''), tile('Active leases', fmtNum(S.leases.length), \`\${fmtNum(S.leaseMissing)} missing lease data\`)])}
      <p class="rs-foot">Click a unit to view or edit it (lease details are in the form). Hour meter, PM dates, open items and lease status calculate from the logs.</p></section>\` +
    \`<section class="card log-card">\${logBlock('mheAssets', { stateKey: 'mhe:assets', filter: siteMatch })}</section>\`;
}

function hoursTab(S) {
  const H = hoursRows().filter(siteMatch), flagged = H.filter(h => h.check !== 'OK' && h.check !== 'Excluded');
  const lastWeek = H.map(h => h.weekEnding).filter(isISO).sort().at(-1) || '';
  const svc = serviceRows().filter(siteMatch), yr = todayISO().slice(0, 4);
  return \`<section class="card rail-sum"><div class="rs-title">Hours log\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Readings', fmtNum(H.length), lastWeek ? \`latest week ending \${us(lastWeek)}\` : 'none yet'), tile('Readings to check', fmtNum(flagged.length), 'End < Start · over max · below prior · unknown serial', flagged.length ? 'warn' : 'good'),
        tile('Avg hours / truck / wk', S.avgHrs === '' ? 'n/a' : fmtNum(S.avgHrs, 1), \`\${fmtNum(S.hrsTrucks)} trucks reporting\`), tile('Trucks with no reading', fmtNum(S.trucks.filter(a => a.hourMeter === '').length), 'powered trucks')])}
      <div class="rail-cust-chart">\${mheChart('Truck hours by week and site (OK readings)', 'ch-mhe-hours', 240, 'Hours used per week, stacked by site')}</div>
      \${flagged.length ? \`<p class="rs-foot"><a href="#" data-show-flagged>Show the \${fmtNum(flagged.length)} reading\${flagged.length === 1 ? '' : 's'} to check ▸</a></p>\` : ''}</section>
    <section class="card log-card">\${logBlock('mheHours', { stateKey: 'mhe:hours', filter: siteMatch })}</section>
    <section class="card rail-sum"><div class="rs-title">Service log\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Open items', fmtNum(S.open.length), S.open.length ? \`oldest \${fmtNum(S.oldestOpen)} days open\` : 'nothing waiting', S.open.length ? 'warn' : 'good'), tile('PM overdue', fmtNum(S.pmOverdue.length), \`\${fmtNum(S.pmDue.length)} due in 14 days · interval \${fmtNum(config().pmInterval)} days\`, S.pmOverdue.length ? 'bad' : 'good'),
        tile(\`Service events \${yr}\`, fmtNum(svc.filter(s => String(s.serviceDate).startsWith(yr)).length), \`\${fmtNum(svc.length)} on file\`), tile(\`Spend \${yr}\`, fmtMoney(S.spendYTD), 'invoice amounts')])}
      <div class="rail-cust-chart">\${mheChart('Service spend by month and category', 'ch-mhe-spend', 240, 'Invoice dollars per month stacked by service category')}</div></section>
    <section class="card log-card">\${logBlock('mheService', { stateKey: 'mhe:service', filter: siteMatch })}</section>\`;
}

function operatorsTab() {
  const people = operatorPeople().filter(p => p.certs.some(opMatch));
  const certs = people.flatMap(p => p.certs.filter(opMatch));
  const n = s => certs.filter(c => (typeof s === 'function' ? s(c) : c.status === s)).length;
  const step = (label, d) => \`<span class="mhe-step \${isISO(d) ? 'ok' : 'miss'}" title="\${esc(label)}\${isISO(d) ? ' ' + us(d) : ' — not recorded'}"><i>\${isISO(d) ? '✓' : '!'}</i>\${esc(label)}<b>\${isISO(d) ? us(d) : '—'}</b></span>\`;
  const card = p => \`<article class="mhe-op \${certTone(p.worst)}">
      <header><div><h3>\${esc(p.name)}</h3><p>\${esc(p.building || 'Not Recorded')}\${p.home ? \` · home \${esc(p.home)}\` : ''} · <span class="\${p.roster === 'Active' ? '' : 'mhe-warn'}">\${esc(p.roster === 'Active' ? 'Active on roster' : p.roster)}</span></p></div>
        <div class="mhe-op-st">\${pill(p.worst, certTone(p.worst))}<small>\${p.canOperate.length ? \`Cleared: \${esc(p.canOperate.join(', '))}\` : 'Not cleared to operate'}</small></div></header>
      \${p.certs.filter(opMatch).map(c => \`<div class="mhe-cert" data-cert="\${esc(c.id)}" tabindex="0" role="button" aria-label="Open \${esc(c.employee)} \${esc(c.equipment)} certification">
        <div class="mhe-cert-h"><b>\${esc(c.equipment || '—')}</b>\${c.certNo ? \`<span class="mono">Cert #\${esc(c.certNo)}</span>\` : ''}<span>Trainer: \${c.trainer ? esc(c.trainer) : '<em class="mhe-warn">not recorded</em>'}</span>
          <span class="grow"></span><span>Expires \${c.expires ? us(c.expires) : '—'}\${c.daysToExpiry !== '' ? \` (\${c.daysToExpiry < 0 ? \`\${fmtNum(-c.daysToExpiry)} days ago\` : \`\${fmtNum(c.daysToExpiry)} days\`})\` : ''}</span>\${pill(c.status, certTone(c.status))}</div>
        <div class="mhe-steps">\${c.steps.map(([l, d]) => step(l, d)).join('<span class="mhe-arrow">›</span>')}</div>
        \${c.notes ? \`<p class="mhe-note">\${esc(c.notes)}</p>\` : ''}</div>\`).join('')}
    </article>\`;
  return \`<section class="card rail-sum"><div class="rs-title">Operators &amp; certifications\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      \${tiles([tile('Operators', fmtNum(people.length), \`\${fmtNum(certs.length)} certifications on file\`), tile('Cleared to operate', fmtNum(people.filter(p => p.canOperate.length).length), 'at least one current certification', 'good'),
        tile('Expiring', fmtNum(n(c => /^Expiring/.test(c.status))), \`within \${fmtNum(config().expiringDays)} days\`, n(c => /^Expiring/.test(c.status)) ? 'warn' : ''), tile('Expired', fmtNum(n('Expired')), 'retrain and re-evaluate', n('Expired') ? 'bad' : 'good'),
        tile('Dates to check', fmtNum(n(c => c.status === 'Check Dates' || c.status === 'Missing Expiry')), 'expiry missing or on/before the card date', n(c => c.status === 'Check Dates' || c.status === 'Missing Expiry') ? 'warn' : ''),
        tile('Missing prerequisites', fmtNum(certs.filter(c => c.missing.length).length), 'classroom, practical, evaluation, card or trainer not recorded', certs.some(c => c.missing.length) ? 'warn' : '')])}
      <div class="toolbar mhe-op-tools"><input type="search" class="search" placeholder="Search operators…" value="\${esc(st.opQ || '')}" data-op-q aria-label="Search operators">
        <select data-op-st aria-label="Status"><option value="">All statuses</option>\${['Needs action', 'Current', 'Expiring', 'Expired', 'Check Dates', 'Missing Expiry'].map(s => \`<option \${st.opSt === s ? 'selected' : ''}>\${s}</option>\`).join('')}</select>
        <span class="grow"></span>\${store.can('edit') ? '<button class="btn primary" data-add-cert>+ Add certification</button>' : ''}</div>
      <p class="rs-foot">Prerequisites in order: classroom (formal instruction) › practical (hands-on training) › evaluation › certified › card issued. OSHA 1910.178(l) requires a re-evaluation at least every 3 years. Click a certification to edit it.</p></section>
    <div class="mhe-ops">\${people.filter(p => {
      const q = norm(st.opQ || ''); if (q && !norm([p.name, p.building, ...p.certs.map(c => c.equipment + ' ' + c.trainer + ' ' + c.certNo)].join(' ')).includes(q)) return false;
      const s = st.opSt || ''; if (!s) return true;
      return p.certs.some(c => (s === 'Needs action' ? c.status !== 'Current' || c.missing.length : s === 'Expiring' ? /^Expiring/.test(c.status) : c.status === s));
    }).map(card).join('') || '<p class="muted">No operators match.</p>'}</div>
    <section class="card log-card"><div class="rs-title">Certification log</div>\${logBlock('mheOperators', { stateKey: 'mhe:ops', filter: opMatch })}</section>\`;
}

function exceptionsTab(S) {
  const pairs = S.A.filter(a => isTruck(a) && a.paired).map(a => ({ truck: a, att: S.A.find(x => x.assetId === a.paired) }));
  const unpaired = S.A.filter(a => /attachment/i.test(a.assetClass || '') && !a.paired);
  return \`<section class="card rail-sum"><div class="rs-title">Exceptions\${st.site ? \` — \${esc(siteLabel(st.site))}\` : ''}</div>
      <div class="mhe-sev">\${['Critical', 'High', 'Medium', 'Low'].map(s => \`<div class="mhe-sev-cell \${sevTone(s)}"><b>\${fmtNum(S.openExc.filter(x => x.severity === s).length)}</b><span>\${s} open</span></div>\`).join('')}<div class="mhe-sev-cell good"><b>\${fmtNum(S.exc.length - S.openExc.length)}</b><span>Closed</span></div></div></section>
    <section class="card log-card">\${logBlock('mheExceptions', { stateKey: 'mhe:exc', filter: x => !st.site || String(x.site || '').includes(st.site) })}</section>
    \${rsSection(\`Truck ↔ attachment pairings <span class="pill info">\${fmtNum(pairs.length)} pairs</span>\`, \`<div class="table-wrap"><table class="perf">
      <thead><tr><th class="cust">Truck</th><th class="cust">Truck serial</th><th class="cust">Attachment</th><th class="cust">Attachment serial</th><th class="cust">Site</th><th class="cust">Truck type</th><th class="cust">Attachment size</th><th>Data status</th></tr></thead>
      <tbody>\${pairs.map(({ truck: t, att: a }) => \`<tr><td class="cust"><b>\${esc(t.assetId)}</b></td><td class="cust mono">\${esc(t.serial)}</td><td class="cust"><b>\${esc(t.paired)}</b></td><td class="cust mono">\${esc(a?.serial || '')}</td><td class="cust">\${esc(t.site)}</td><td class="cust">\${esc(t.family || t.type)}</td><td class="cust">\${esc(a?.attachSize || '')}</td><td>\${pill(t.dataStatus || '—', t.dataStatus === 'Verified' ? 'good' : t.dataStatus === 'Conflict' ? 'bad' : 'warn')}</td></tr>\`).join('') || '<tr><td colspan="8">No pairings recorded.</td></tr>'}</tbody></table></div>
      <p class="rs-foot">Pairings come from each unit's Paired Asset (Fleet register).\${unpaired.length ? \` \${fmtNum(unpaired.length)} attachment\${unpaired.length === 1 ? ' is' : 's are'} not paired with a truck.\` : ''}</p>\`)}\`;
}

function importTab() {
  const cfg = config(), have = COLLS.filter(c => c.startsWith('mhe') && c !== 'mheConfig').map(c => [c, store.rows(c).length]);
  const p = parsed;
  return \`\${rsSection('Import the MHE Fleet Register workbook', \`<div class="mhe-pad">
      <p>Drop <b>Piper Logistics - MHE Fleet Register.xlsx</b> (or a newer copy). The app reads the Fleet Register, Lease Schedule, Hours Log, Service Log, Operators and Exceptions sheets. Calculated columns (hour meter, PM dates, statuses, days to expiry …) are worked out by the app, so only the entered data is loaded.</p>
      <label class="wk-drop" data-drop tabindex="0"><input type="file" accept=".xlsx,.xlsm" data-file hidden><b>\${busy ? 'Reading…' : 'Drop the workbook here or click to choose'}</b><small>Nothing is saved until you press Load.</small></label>
      \${p ? \`<p><b>\${esc(p.file)}</b></p>\${planTableHtml(planImport(p))}
        <div class="toolbar"><button class="btn primary" data-load \${busy ? 'disabled' : ''}>Update the app from this file</button><button class="btn ghost" data-cancel>Cancel</button></div>\` : ''}
      <p class="rs-foot">In the app now: \${have.map(([c, nn]) => \`\${{ mheAssets: 'assets', mheHours: 'hour readings', mheService: 'service events', mheOperators: 'certifications', mheExceptions: 'exceptions' }[c]} \${fmtNum(nn)}\`).join(' · ')}.</p></div>\`)}
    \${rsSection('MHE settings', \`<form class="mhe-pad mhe-cfg" data-cfg>
      <label>PM interval (days) <input type="number" name="pmInterval" min="7" max="365" value="\${cfg.pmInterval}"></label>
      <label>Weekly hours flag (hrs / week) <input type="number" name="maxHrsWeek" min="10" max="168" value="\${cfg.maxHrsWeek}"></label>
      <label>Certification "expiring" window (days) <input type="number" name="expiringDays" min="7" max="365" value="\${cfg.expiringDays}"></label>
      \${store.can('edit') ? '<button class="btn primary">Save settings</button>' : ''}</form>\`)}\`;
}

// ---------------------------------------------------------------- view
export default {
  needs: () => COLLS,
  render(p) {
    const q = p.query || {};
    if (q.tab && TABS.some(([k]) => k === q.tab)) st.tab = q.tab;
    if (q.site !== undefined) st.site = SITES.includes(q.site) ? q.site : '';
    if (st.tab === 'import' && !store.can('edit')) st.tab = 'dashboard';
    const S = fleetStats(st.site);
    const siteSel = \`<label class="xl-chg">Site <select data-site aria-label="Site"><option value="">All sites</option>\${SITES.map(s => \`<option value="\${esc(s)}" \${s === st.site ? 'selected' : ''}>\${esc(siteLabel(s))}</option>\`).join('')}</select></label>\`;
    const meta = \`<b>Assets</b><span class="xl-year">\${fmtNum(S.total)}</span><b>As of</b><span class="xl-thru">\${us(todayISO())}</span>\${st.tab === 'import' ? '' : siteSel}\`;
    const empty = !store.rows('mheAssets').length;
    const body = st.tab === 'import' ? importTab()
      : empty ? \`<section class="card rail-perf"><div class="mhe-pad"><h3>No MHE data yet</h3><p>\${store.can('edit') ? 'Load the MHE Fleet Register workbook on the <a href="#/mhe?tab=import">Import / settings</a> tab to fill the register, hours, service, operator and exception logs.' : 'Ask a supervisor to load the MHE Fleet Register workbook.'}</p></div></section>\`
      : st.tab === 'register' ? registerTab(S) : st.tab === 'hours' ? hoursTab(S) : st.tab === 'operators' ? operatorsTab() : st.tab === 'exceptions' ? exceptionsTab(S)
      : \`<section class="card rail-top">\${topStrip(S)}</section>\` + watchlist(S) + compositionTable(S) + mixTable(S) + exceptionsAndLeases(S) + trends() +
        \`<p class="rail-note">Material handling equipment at every Piper site: powered industrial trucks, attachments (clamps, forks) and facility equipment. Hours come from the weekly Hours Log (only OK readings count); PM status from the Service Log (\${fmtNum(config().pmInterval)}-day interval); operator status from certification expiry dates. Greensboro = building 6021, Fulton = 6049.</p>\`;
    const desc = { dashboard: 'Fleet size, ownership, maintenance, hours, operator certifications and data exceptions across Atlanta, Indiana and Ohio.', register: 'Every truck, attachment and facility unit with its ownership, data status and calculated hour meter / PM / lease columns.', hours: 'Weekly hour-meter readings and the service log (PMs, repairs, tires, batteries, inspections and invoices).', operators: 'Each operator, the equipment they are certified on and every prerequisite: classroom, practical, evaluation, certification, card and expiry.', exceptions: 'Register data issues to resolve, and which attachment goes with which truck.', import: 'Load the MHE Fleet Register workbook and set the PM interval, weekly hours flag and certification window.' }[st.tab];
    return \`<div class="rail-theme rail-xl mhe">\${head(\`MHE Fleet — \${TABS.find(([k]) => k === st.tab)[1]}\`, desc, meta)}\${chips()}\${body}</div>\`;
  },
  after(root, p, rerender) {
    const go = () => { location.hash = \`#/mhe?tab=\${st.tab}\${st.site ? '&site=' + encodeURIComponent(st.site) : ''}\`; };
    $('[data-site]', root)?.addEventListener('change', e => { st.site = e.target.value; go(); });
    bindLogs(root, rerender);
    if (st.tab === 'dashboard' && store.rows('mheAssets').length) drawDashboard(fleetStats(st.site));
    if (st.tab === 'hours') drawDashboard(fleetStats(st.site));
    $('[data-show-flagged]', root)?.addEventListener('click', e => {
      e.preventDefault();
      Object.assign(logState('mhe:hours'), { ids: hoursRows().filter(siteMatch).filter(h => h.check !== 'OK' && h.check !== 'Excluded').map(h => h.id), year: 'all', q: '', limit: 200 });
      rerender(); setTimeout(() => document.querySelector('[data-state="mhe:hours"]')?.scrollIntoView({ behavior: 'smooth' }), 50);
    });
    // Operators: search / status filter, open a certification, add one.
    const opQ = $('[data-op-q]', root); let t;
    opQ?.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => { st.opQ = opQ.value; rerender(); setTimeout(() => { const n = $('[data-op-q]'); n?.focus(); n?.setSelectionRange(n.value.length, n.value.length); }); }, 250); });
    $('[data-op-st]', root)?.addEventListener('change', e => { st.opSt = e.target.value; rerender(); });
    $$('[data-cert]', root).forEach(el => {
      const open = () => editRow('mheOperators', derive('mheOperators').find(r => r.id === el.dataset.cert));
      el.addEventListener('click', open); el.addEventListener('keydown', e => { if (e.key === 'Enter') open(); });
    });
    $('[data-add-cert]', root)?.addEventListener('click', () => editRow('mheOperators', null, st.site ? { building: st.site } : {}));
    // Import
    const file = $('[data-file]', root), drop = $('[data-drop]', root);
    const read = async f => {
      if (!f) return; busy = true; rerender();
      try { parsed = await readRegister(f); } catch (e) { parsed = null; toast(e.message, 'bad'); }
      busy = false; rerender();
    };
    drop?.addEventListener('click', () => file.click());
    file?.addEventListener('change', () => read(file.files[0]));
    drop?.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('over'); });
    drop?.addEventListener('dragleave', () => drop.classList.remove('over'));
    drop?.addEventListener('drop', e => { e.preventDefault(); drop.classList.remove('over'); read(e.dataTransfer.files[0]); });
    $('[data-cancel]', root)?.addEventListener('click', () => { parsed = null; rerender(); });
    $('[data-load]', root)?.addEventListener('click', async () => {
      const d = parsed; if (!d) return;
      busy = true; rerender();
      try {
        const plan = await applyImport(d);
        toast(\`MHE Fleet updated: \${plan.reduce((t, x) => t + x.add.length, 0)} new, \${plan.reduce((t, x) => t + x.upd.length, 0)} updated rows\`);
        parsed = null; st.tab = 'dashboard';
      } catch (e) { toast(e.message, 'bad'); }
      busy = false; go(); rerender();
    });
    $('[data-cfg]', root)?.addEventListener('submit', async e => {
      e.preventDefault(); const f = new FormData(e.target);
      try { await store.set('mheConfig', 'main', { pmInterval: +f.get('pmInterval') || 90, maxHrsWeek: +f.get('maxHrsWeek') || 100, expiringDays: +f.get('expiringDays') || 60 }); toast('MHE settings saved'); } catch (err) { toast(err.message, 'bad'); }
    });
  },
};`]);
